mapper.select:
SELECT * FROM ( SELECT rownum rn, TB.* FROM ( SELECT DISTINCT AD.ADOC_ID, AD.APPR_STATUS, FIND_CODENAME(AD.APPR_STATUS, 'COM106') AS APPR_STATU_NAME , AD.ALINE_ID, AD.DFORM_ID, AD.DFORM_NAME, AD.ADOC_TITLE, AD.MBER_ID, AD.MBER_NM, AD.REG_DATE, AD.UPD_DATE FROM VW_APPRDOC_DETAIL AD JOIN APPRLINE AL ON AD.aline_Id = AL.aline_Id JOIN APPRLINEDETAIL ALD ON AL.aline_Id = ALD.aline_Id WHERE APPR_STATUS IN ('A1', 'A2', 'A3') AND ALD.MBER_ID = #{mberId}
AND AD.DFORM_NAME LIKE '%' || #{searchKeyword} || '%'
AND AD.MBER_NM LIKE '%' ||#{searchKeyword}|| '%'
ORDER BY 1 DESC ) TB ) WHERE rn BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

SELECT COUNT(1) FROM VW_APPRDOC_DETAIL AD JOIN APPRLINE AL ON AD.aline_Id = AL.aline_Id JOIN APPRLINEDETAIL ALD ON AL.aline_Id = ALD.aline_Id WHERE APPR_STATUS IN ('A1', 'A2', 'A3') AND ALD.MBER_ID = #{mberId}
AND AD.DFORM_NAME LIKE '%' || #{searchKeyword} || '%'
AND AD.MBER_NM LIKE '%' ||#{searchKeyword}|| '%'

SELECT * FROM ( SELECT rownum rn, TB.* FROM ( SELECT AD.ADOC_ID, AD.APPR_STATUS, FIND_CODENAME(AD.APPR_STATUS, 'COM106') AS APPR_STATU_NAME , AD.ALINE_ID, AD.DFORM_ID, AD.DFORM_NAME, AD.ADOC_TITLE, AD.MBER_ID, AD.MBER_NM, AD.REG_DATE, AD.UPD_DATE FROM VW_APPRDOC_DETAIL AD WHERE AD.MBER_ID = #{mberId}
AND DFORM_ID LIKE '%' || #{searchKeyword} || '%'
AND MBER_ID LIKE '%' ||#{searchKeyword}|| '%'
ORDER BY 1 DESC ) TB ) WHERE rn BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

SELECT COUNT(1) FROM VW_APPRDOC_DETAIL AD WHERE AD.MBER_ID = #{mberId}
AND DFORM_ID LIKE '%' || #{searchKeyword} || '%'
AND MBER_ID LIKE '%' ||#{searchKeyword}|| '%'

